const payload = msg.payload;
const cameraName = payload.camera_name || 'Unknown Camera';
const eventType = payload.event || 'detection';
const state = payload.state;

// Only notify on active detection
if (state === 'active') {
    const icon = eventType === 'person' ? '👤' : '🏃';
    msg.payload = {
        type: 'message',
        content: `${icon} *Alert: ${eventType.toUpperCase()} DETECTED*\n` +
                 `📷 Camera: ${cameraName}\n` +
                 `🕒 Time: ${new Date().toLocaleTimeString('ro-RO')}`,
        parse_mode: 'Markdown'
    };

    // Store last event for status command
    const lastEvents = flow.get('camera_last_events') || {};
    lastEvents[cameraName] = {
        type: eventType,
        time: new Date().toISOString()
    };
    flow.set('camera_last_events', lastEvents);

    return msg;
}

return null;

const topic = msg.topic;
const state = msg.payload;
const cameraName = topic.split('/')[2].replace(/_/g, ' ').toUpperCase();

const healthStore = flow.get('camera_health') || {};
const prevState = healthStore[cameraName];

healthStore[cameraName] = {
    state: state,
    time: new Date().toISOString()
};
flow.set('camera_health', healthStore);

// Notify on state change
if (prevState && prevState.state !== state) {
    const icon = state === 'online' ? '✅' : '❌';
    msg.payload = {
        type: 'message',
        content: `${icon} *Camera Status Change*\n` +
                 `📷 Camera: ${cameraName}\n` +
                 `📊 Status: ${state.toUpperCase()}`,
        parse_mode: 'Markdown'
    };
    return msg;
}

return null;

const healthStore = flow.get('camera_health') || {};
const lastEvents = flow.get('camera_last_events') || {};

let statusText = `📷 *TAPO CAMERA SYSTEM STATUS*\n` +
                 `━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n`;

const cameras = Object.keys(healthStore);

if (cameras.length === 0) {
    statusText += "_No cameras currently reporting status._";
} else {
    cameras.forEach(name => {
        const health = healthStore[name];
        const event = lastEvents[name];
        const icon = health.state === 'online' ? '🟢' : '🔴';

        statusText += `${icon} *${name}*\n` +
                      `   • Status: ${health.state.toUpperCase()}\n`;

        if (event) {
            const eventTime = new Date(event.time).toLocaleTimeString('ro-RO');
            statusText += `   • Last ${event.type}: ${eventTime}\n`;
        }

        statusText += `\n`;
    });
}

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: statusText,
    parse_mode: 'Markdown'
};

return msg;

const payload = msg.payload;
let logEntry = null;

// Determine if it's an event notification or health change
if (msg.topic && msg.topic.includes('event')) {
    // From func_process_camera_event
    const cameraMatch = payload.content.match(/📷 Camera: (.+)/);
    const typeMatch = payload.content.match(/Alert: (.+) DETECTED/);

    logEntry = {
        camera: cameraMatch ? cameraMatch[1] : 'Unknown',
        type: typeMatch ? typeMatch[1].toLowerCase() : 'event',
        message: typeMatch ? `${typeMatch[1]} detected` : 'Motion',
        time: new Date().toISOString(),
        status: 'active'
    };
} else if (msg.topic && msg.topic.includes('health')) {
    // From func_process_camera_health
    const cameraMatch = payload.content.match(/📷 Camera: (.+)/);
    const statusMatch = payload.content.match(/📊 Status: (.+)/);

    logEntry = {
        camera: cameraMatch ? cameraMatch[1] : 'Unknown',
        type: 'health',
        message: statusMatch ? `Camera is ${statusMatch[1]}` : 'Status changed',
        time: new Date().toISOString(),
        status: statusMatch ? statusMatch[1].toLowerCase() : 'unknown'
    };
}

if (!logEntry) return null;

// Update Log in flow context
let eventLog = flow.get('camera_event_log') || [];
eventLog.unshift(logEntry);

// Limit to 50 entries
if (eventLog.length > 50) {
    eventLog = eventLog.slice(0, 50);
}
flow.set('camera_event_log', eventLog);

msg.payload = eventLog;
return msg;
